setInterval(()=>northNativeBackgroundTask('phone-stranger',()=>{phCheckStranger();phCheckStrangerSms();}),60000);setTimeout(()=>northNativeBackgroundTask('phone-stranger',()=>{phCheckStranger();phCheckStrangerSms();}),15000);
