function companionReady(st){return !!(st&&(st.linked||st.demo));}
function companionSourceLabel(st){return st&&st.transport==='local-native'?'本机原生直连 · 这台真实 iPhone':st&&st.linked?'云端安全中转 · 远程真实 iPhone':st&&st.demo?'原型测试数据 · 非真实设备':'等待真实 iPhone 接入';}
function companionScope(v){v=String(v||'').trim();if(/仅内置|只内置|internal/i.test(v))return'internal';if(/仅外置|只外置|external/i.test(v))return'external';if(/内外同时|内外|both/i.test(v))return'both';return'';}
function companionScopeLabel(v){return v==='internal'?'仅内置':v==='external'?'仅外置':'内外同时';}
function companionSetScope(v){const st=companionState();st.defaultScope='both';save();render();toast('已使用统一真实手机管控');}
function companionBindingForInternal(st,internalId){return st&&st.bindings.find(x=>x&&x.internalAppId===internalId)||null;}
function companionExternalById(st,externalId){return st&&st.apps.find(x=>x&&x.id===externalId)||null;}
function companionBoundExternal(st,internalId){const b=companionBindingForInternal(st,internalId);return b?companionExternalById(st,b.externalAppId):null;}
