function companionBindingMirrorsLock(st,binding,app){if(!st||!binding||!LOCKABLE[binding.internalAppId])return false;const external=app||companionExternalById(st,binding.externalAppId);if(!external)return false;return companionComparableAppName(external.name)===companionComparableAppName(LOCKABLE[binding.internalAppId]);}
function companionLastExternalCommand(st,app){if(!st||!app)return null;return (st.commands||[]).find(x=>x&&(x.action==='lock'||x.action==='unlock')&&(x.externalAppId===app.id||(!x.externalAppId&&String(x.detail||'').includes(app.name))))||null;}
function companionSnapshotIsFresh(st,now){const synced=st&&(+st.dynamicSync||+st.lastSync||0);return !!(synced&&Math.max(0,(Number.isFinite(+now)?+now:Date.now())-synced)<=COMPANION_SNAPSHOT_FRESH_MS);}
function companionExternalCommandState(st,app,now){now=Number.isFinite(+now)?+now:Date.now();const fresh=companionSnapshotIsFresh(st,now),row=companionLastExternalCommand(st,app);if(!row)return fresh?{kind:'snapshot',text:app&&app.locked?'iPhone 设备配置含锁':'iPhone 设备配置未含锁'}:{kind:'snapshotStale',text:app&&app.locked?'iPhone 上次设备配置含锁（动态数据较早）':'iPhone 上次设备配置未含锁（动态数据较早）'};if(row.status==='pending'&&now-(+row.ts||0)>COMPANION_COMMAND_PENDING_MS)return {kind:'expired',text:(row.action==='unlock'?'解锁':'锁定')+'命令已过期，未收到 iPhone 回执'};if(row.status==='pending')return {kind:row.action==='unlock'?'pendingUnlock':'pendingLock',text:(row.action==='unlock'?'解锁':'锁定')+'命令等待 iPhone 回执'};if(row.status==='failed'){const message=row.error||(row.result&&row.result.message)||'';return {kind:'failed',text:(row.action==='unlock'?'解锁':'锁定')+'失败'+(message?'：'+message:'')}}const acknowledgedAt=Math.max(+row.acknowledgedAt||0,+row.ts||0);if(!st.lastSync||st.lastSync<acknowledgedAt)return {kind:'awaitSnapshot',text:'设备已回执，等待回执后的新快照'};if(row.action==='unlock'&&app.locked)return {kind:'conflict',text:'解锁配置未移除：iPhone 新快照仍含锁'};if(row.action==='lock'&&!app.locked)return {kind:'conflict',text:'锁定配置未写入：iPhone 新快照未含锁'};return {kind:'confirmed',text:'iPhone 已回执；新快照中'+(row.action==='unlock'?'设备配置已移除锁定':'设备配置含锁')+'，等待真机打开目标 App 验证'+(fresh?'':'（动态数据较早）')};}
