  if(action==='view'){const detail=st.demo?'已查看原型设备状态':'已请求设备状态',log=opt.skipLog?null:companionLog(st,action,detail,st.demo?'completed':'pending',actor);if(!st.demo)companionSendCommand(st,action,null,opt,log);return {ok:true,detail};}
