function companionApplyInternalAction(action,internalId,minutes,actor){if(!LOCKABLE[internalId])return {ok:false,detail:'没有找到内置 App ID'};S.couple.locks=S.couple.locks||{};S.couple.timeLimit=S.couple.timeLimit||{};if(action==='limit'){const m=Math.max(1,Math.min(720,parseInt(minutes,10)||1));S.couple.timeLimit[internalId]=m;return {ok:true,detail:'内置「'+LOCKABLE[internalId]+'」每日 '+m+' 分钟'};}if(action==='lock'){S.couple.locks[internalId]={pwd:genPwd(),time:Date.now(),byCompanion:true,actor};return {ok:true,detail:'已锁定内置「'+LOCKABLE[internalId]+'」'};}if(action==='unlock'){delete S.couple.locks[internalId];return {ok:true,detail:'已解锁内置「'+LOCKABLE[internalId]+'」'};}return {ok:false,detail:'不支持的内置操作'};}
function companionAllExternalIntent(text){const raw=String(text||'').replace(/[「」『』"'《》]/g,'').trim();return /(?:全部|所有)(?:\s*(?:已选|已同步|同步到的|外置|内外|已授权|可控制的|真实\s*iPhone\s*上的))?\s*(?:App|应用|软件)|(?:每一个|一个不留)\s*(?:App|应用|软件)/i.test(raw);}
function companionMentionedExternalTargets(st,text){const apps=Array.isArray(st&&st.apps)?st.apps:[],raw=String(text||'').replace(/[「」『』"'《》]/g,'').toLowerCase(),aliases=name=>{const full=String(name||'').trim().toLowerCase(),values=[full];if(full==='chatgpt'||full==='chat gpt')values.push('gpt');if(full==='微信'||full==='wechat')values.push('wx');return [...new Set(values.filter(Boolean))];},aliasCounts=new Map(),items=[];apps.forEach((app,index)=>aliases(app&&app.name).forEach(alias=>{aliasCounts.set(alias,(aliasCounts.get(alias)||0)+1);items.push({app,index,name:alias});}));const hits=[];for(const item of items.filter(x=>x.name&&aliasCounts.get(x.name)===1).sort((a,b)=>b.name.length-a.name.length||a.index-b.index)){let from=0;while(from<=raw.length-item.name.length){const at=raw.indexOf(item.name,from);if(at<0)break;const end=at+item.name.length,ascii=/^[a-z0-9._+-]+$/i.test(item.name),leftOK=!ascii||at===0||!/[a-z0-9]/i.test(raw[at-1]),rightOK=!ascii||end===raw.length||!/[a-z0-9]/i.test(raw[end]),covered=hits.some(h=>at>=h.start&&end<=h.end);if(leftOK&&rightOK&&!covered)hits.push({app:item.app,index:item.index,start:at,end});from=at+Math.max(1,item.name.length);}}const seen=new Set();return hits.sort((a,b)=>a.start-b.start||a.index-b.index).map(x=>x.app).filter(app=>{const id=String(app&&app.id||'');if(!id||seen.has(id))return false;seen.add(id);return true;});}
function companionExternalTargetsByText(st,text){const apps=Array.isArray(st&&st.apps)?st.apps:[];if(companionAllExternalIntent(text))return apps.slice();return companionMentionedExternalTargets(st,text);}
function companionRoleReferenceCount(text){const m=String(text||'').match(/(?:这|那|前面(?:说的)?)?\s*(\d{1,2}|[一二两三四五六七八九十两])\s*(?:个|款|种)/);if(!m)return 0;if(/^\d+$/.test(m[1]))return Math.max(0,parseInt(m[1],10)||0);return {一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9,十:10}[m[1]]||0;}
function companionLatestUserText(c){const arr=c&&typeof msgs==='function'?msgs(c.id)||[]:[];for(let i=arr.length-1;i>=0;i--){const row=arr[i];if(row&&row.role==='user'&&row.type!=='sys')return typeof msgToText==='function'?msgToText(row)||'':String(row.content||'');}return '';}
function companionRecentExternalGroup(st,c,count){const arr=c&&typeof msgs==='function'?msgs(c.id)||[]:[];for(let i=arr.length-1,checked=0;i>=0&&checked<12;i--){const row=arr[i];if(!row||row.type==='sys')continue;checked++;const value=typeof msgToText==='function'?msgToText(row)||'':String(row.content||''),targets=companionMentionedExternalTargets(st,value);if(count>0&&targets.length===count)return targets;if(!count&&targets.length>=2)return targets;}return [];}
function companionRecentUniqueExternal(st,c){const arr=c&&typeof msgs==='function'?msgs(c.id)||[]:[];for(let i=arr.length-1,checked=0;i>=0&&checked<10;i--){const row=arr[i];if(!row||row.type==='sys')continue;checked++;const value=typeof msgToText==='function'?msgToText(row)||'':String(row.content||''),targets=companionMentionedExternalTargets(st,value);if(targets.length===1)return targets[0];if(targets.length>1)return null;}return null;}
